class Solution { public boolean sequenceReconstruction(int[] nums,int[][] seqs) { int n=nums.length;List<Set<Integer>>g=new ArrayList<>();for(int i=0;i<=n;i++)g.add(new HashSet<>());int[] d=new int[n+1];boolean[] seen=new boolean[n+1];for(int[] s:seqs){for(int x:s)seen[x]=true;for(int i=1;i<s.length;i++)if(g.get(s[i-1]).add(s[i]))d[s[i]]++;}for(int i=1;i<=n;i++)if(!seen[i])return false;ArrayDeque<Integer>q=new ArrayDeque<>();for(int i=1;i<=n;i++)if(d[i]==0)q.add(i);int k=0;while(!q.isEmpty()){if(q.size()!=1)return false;int u=q.remove();if(k>=n||nums[k++]!=u)return false;for(int v:g.get(u))if(--d[v]==0)q.add(v);}return k==n;} }
